import{_ as n,o as a,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — View Agency Profile (FR 3.4.4)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-4-view-agency-profile/plan.md","filePath":"feature/agency-workspace/3-4-4-view-agency-profile/plan.md"}'),o={name:"feature/agency-workspace/3-4-4-view-agency-profile/plan.md"};function d(i,e,r,l,s,p){return a(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="plan-—-view-agency-profile-fr-3-4-4" tabindex="-1">Plan — View Agency Profile (FR 3.4.4) <a class="header-anchor" href="#plan-—-view-agency-profile-fr-3-4-4" aria-label="Permalink to &quot;Plan — View Agency Profile (FR 3.4.4)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — hiển thị Profile công khai của Agency (name, logo, description).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>AgencyServiceImpl.getAgency()</code></td></tr><tr><td>File đã có</td><td><code>AgencyController</code> (<code>GET /api/v1/agencies/{agencyId}</code>), <code>AgencyRepository</code>, <code>AgencyResponse</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/agencies/{agencyId}</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;AgencyResponse&gt;</span></span>
<span class="line"><span>   data = { id, name, ownerId, logoUrl, description, category, companySize,</span></span>
<span class="line"><span>            website, phone, location, brandColor, logoIcon, tagline,</span></span>
<span class="line"><span>            foundedYear, facebookUrl, linkedinUrl, instagramUrl,</span></span>
<span class="line"><span>            status, createdAt, updatedAt }</span></span></code></pre></div><p>Khác so với spec.md (đề xuất <code>GET /api/v1/agencies/{id}/profile</code>):</p><ul><li><strong>Bỏ hậu tố <code>/profile</code></strong> — dùng thẳng <code>GET /{agencyId}</code> để thống nhất với <code>PUT /{agencyId}</code> (update) và <code>DELETE /{agencyId}</code> (remove), tránh 2 route cùng trả 1 Agency. Frontend gọi <code>/agency/:id</code> chung.</li><li>Response không có <code>yearsActive</code>/portfolio — ngoài scope, chỉ trả field entity có sẵn.</li><li><strong>Yêu cầu auth + quyền</strong>: controller nhận <code>@AuthenticationPrincipal AuthenticatedUser currentUser</code>; service check OWNER (<code>agency.ownerId == currentUser.id</code>) hoặc có <code>AgencyMember</code> (<code>agencyMemberRepository.findByAgencyIdAndUserId</code>) → nếu không, <code>400 NOT_AGENCY_MEMBER</code>.</li></ul><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Đọc <code>agencies</code> qua <code>findById(agencyId)</code> + <code>agency_members</code> qua <code>findByAgencyIdAndUserId(agencyId, userId)</code>. Không migration.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li><code>findAgencyOrThrow(agencyId)</code> → nếu không có, throw <code>AGENCY_NOT_FOUND</code> (404).</li><li><code>isOwner = agency.getOwnerId().equals(currentUser.getId())</code>.</li><li><code>isMember = agencyMemberRepository.findByAgencyIdAndUserId(agencyId, currentUser.getId()).isPresent()</code>.</li><li><code>!isOwner &amp;&amp; !isMember</code> → throw <code>NOT_AGENCY_MEMBER</code> (400).</li><li>Map → <code>AgencyResponse</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>Agency</code> entity + repository, <code>AgencyMember</code> repository (đã có)</td></tr><tr><td>Bị chặn</td><td><code>Update</code> (3.4.5), <code>Remove</code> (3.4.6) — dùng chung <code>findAgencyOrThrow</code></td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Bỏ public view:</strong> trước đây endpoint không check gì (public đọc). Nay đã siết còn OWNER/MEMBER — nếu BA cần trang giới thiệu công khai cho Client tiềm năng xem trước khi ký hợp đồng thì phải mở route public riêng (chưa có). Cần BA xác nhận lại yêu cầu public.</li></ul>`,16)])])}const u=n(o,[["render",d]]);export{g as __pageData,u as default};
